#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // This is a simple implementation and may not handle all edge cases
    // For a more robust solution, consider using a markdown library like libmarkdown
    // or markdown.js.

    std::string html;
    std::stringstream ss;
    ss << markdown;
    html = ss.str();
    return html;
}

int main() {
    std::string markdown = "# Title\n\nThis is a markdown text.\n\n*";
    std::string html = markdownToHtml(markdown);
    std::cout << "HTML Output: " << html << std::endl;
    return 0;
}
```

